set-variable.value:
@{
      try {
        var body = context.Request.Body.As<JObject>(preserveContent: true);
        if (body["model"]?.Type != JTokenType.String) { return false; }
        if (!JArray.Parse(System.Text.Encoding.UTF8.GetString(Convert.FromBase64String("{{pernova-models-json}}"))).Values<string>().Contains((string)body["model"])) { return false; }
        if (body["max_output_tokens"]?.Type != JTokenType.Integer) { return false; }
        var max = (int)body["max_output_tokens"];
        if (max < 1 || max > 2048) { return false; }
        // No remote tools, saved server state, background work, or streamed accounting on this route.
        if (body["store"]?.Type != JTokenType.Boolean || (bool)body["store"]) { return false; }
        if (body["stream"] != null && (body["stream"].Type != JTokenType.Boolean || (bool)body["stream"])) { return false; }
        if (body["background"] != null && (body["background"].Type != JTokenType.Boolean || (bool)body["background"])) { return false; }
        // The backend explicitly sends tools=[]; permit that shape but never nonempty tools.
        if (body["tools"] != null) {
          var tools = body["tools"] as JArray;
          if (tools == null || tools.Count != 0) { return false; }
        }
        foreach (var key in new [] { "tool_choice", "previous_response_id", "conversation", "agent" }) {
          if (body[key] != null) { return false; }
        }
        return body["input"] != null;
      } catch { return false; }
    }
